export const productVolume=(t,total=60,duration=60)=>{if(!Number.isFinite(t)||t<0||!(total>0)||!(duration>0))throw Error('Invalid curve input');return t>=duration?total:total*(1-(1-t/duration)**2);};
export const productSlope=(t,total=60,duration=60)=>t>=duration?0:2*total/duration*(1-t/duration);
export const tangentAt=(t,tilt=4,total=60,duration=60)=>({time:t,volume:productVolume(t,total,duration),slope:Number(tilt)/4});
const near=(v,n,tol=.01)=>String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)-n)<=tol;
export const graphTasks=[{id:'plot',title:'Place the readings',prompt:'Time/s:0,20,40,60. Gas volume/cm³:0,30,45,50. Enter the three non-zero readings in their labelled time positions.'},{id:'compare',title:'Compare the two runs',prompt:'Both runs have the same limiting reactant and final volume. Compare the labelled curves.'},{id:'tangent',title:'Fit the tangent at30 s',prompt:'Tilt the straight line until it follows the curve’s direction where the marked point touches. Then compare the rate at30 s with the rate at the plateau.'}];
export function graphCorrect(t,a){if(t.id==='plot')return near(a.p20,30)&&near(a.p40,45)&&near(a.p60,50);if(t.id==='compare')return a.fast==='A'&&a.final==='same';return near(a.tilt,4,0)&&a.rate==='greater';}
export const catalystTasks=[{id:'path',title:'Change the pathway',prompt:'Keep reactant and product levels fixed. Lower the peak to show a catalysed pathway.',fields:[['peak','Pathway peak',[['90','Same peak'],['65','Lower peak'],['100','Higher peak']],'65'],['change','Overall energy change',[['same','Unchanged'],['more','Larger'],['zero','Always zero']],'same']]},{id:'evidence',title:'Read the controlled evidence',prompt:'With X, gas reaches60 cm³ in20 s; without X, it reaches60 cm³ in60 s. Other conditions match. X is recovered afterwards with unchanged amount.',fields:[['role','Role of X',[['catalyst','Catalyst supported'],['fuel','Consumed fuel'],['product','Extra gas product']],'catalyst'],['yield','Final gas amount',[['same','Same'],['greater','Greater with X'],['less','Less with X']],'same']]},{id:'enzyme',title:'Choose a biological catalyst',prompt:'An enzyme speeds one biological reaction. Must it also catalyse every other reaction?',fields:[['type','The enzyme is a…',[['catalyst','Biological catalyst'],['reactant','Net consumed reactant'],['inert','Necessarily inert substance']],'catalyst'],['specific','Another reaction',[['test','Needs a suitable catalyst'],['always','Always uses this same enzyme'],['none','Cannot use any catalyst']],'test']]}];
export const catalystCorrect=(t,a)=>t.fields.every(([id,,,key])=>a[id]===key);
